// Contracts from the webhook body, or fictional sample data (from the Sub4Me example). Without asOf the reference date is fixed (19 Oct 2026), so the demo gives the same result every day.
const body = $input.first().json.body || {};
const valid = (d) => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d) && !Number.isNaN(Date.parse(d));
const asOf = valid(body.asOf) ? body.asOf : '2026-10-19';
const withinDays = Number.isFinite(body.withinDays) ? Math.max(1, Math.min(365, Math.round(body.withinDays))) : 30;
const sample = [
  { id: 'C-2023-0390', product: 'Ariba Procurement', end: '2027-01-31', noticeDays: 90 },
  { id: 'C-2025-0041', product: 'SuccessFactors Employee Central', end: '2026-12-31', noticeDays: 90 },
  { id: 'C-2026-0012', product: 'AI units (Joule, AI Core, Document AI)', end: '2026-12-31', noticeDays: 60 },
  { id: 'C-2024-0233', product: 'Business Technology Platform', end: '2027-03-31', noticeDays: 90 },
  { id: 'C-2024-0187', product: 'S/4HANA Cloud Private Edition', end: '2028-12-31', noticeDays: 180 },
];
const given = Array.isArray(body.contracts) ? body.contracts.filter((x) => x && typeof x.id === 'string' && valid(x.end) && Number.isFinite(x.noticeDays)) : null;
const contracts = given && given.length ? given : sample;
return contracts.map((x) => ({ json: { ...x, asOf, withinDays } }));

// Report for the account owner. Ends in "draft only": nothing is sent, a person decides about notice or renewal.
const items = $input.all().map((i) => i.json).sort((a, b) => a.daysLeft - b.daysLeft);
const alerts = items.filter((i) => i.status === 'alert');
const passed = alerts.filter((i) => i.daysLeft < 0);
const asOf = items[0].asOf;
const withinDays = items[0].withinDays;
const lines = [
  `Contract notice check as of ${asOf}: ${items.length} contracts, ${alerts.length} with a notice deadline within ${withinDays} days or already passed (${passed.length} passed).`,
  ...alerts.map((a) => `- ${a.message}`),
  alerts.length ? 'Draft only: nothing is sent. The account owner decides about notice or renewal.' : 'Nothing to do now.',
];
return [{ json: { asOf, withinDays, total: items.length, alerts: alerts.length, passed: passed.length, contracts: items.map((i) => ({ id: i.id, product: i.product, end: i.end, noticeDays: i.noticeDays, noticeDeadline: i.noticeDeadline, daysLeft: i.daysLeft, status: i.status })), digest: lines.join('\n') } }];
